-- PKG_DMF0014 — 적용 후 확인 (SCM_MGR · 조회 전용)
SET PAGESIZE 200 LINESIZE 300

SELECT 'PKG_DMF0014' OBJ, 'PACKAGE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0014' AND OBJECT_TYPE = 'PACKAGE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_DMF0014' AND TYPE = 'PACKAGE' AND LINE > 1) = 202578492769 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'PKG_DMF0014' OBJ, 'PACKAGE BODY' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0014' AND OBJECT_TYPE = 'PACKAGE BODY') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_DMF0014' AND TYPE = 'PACKAGE BODY' AND LINE > 1) = 24197901487929 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('PKG_DMF0014') ORDER BY NAME, TYPE, SEQUENCE;
SELECT OBJECT_NAME PKG, PROCEDURE_NAME MEMBER FROM USER_PROCEDURES WHERE OBJECT_NAME = 'PKG_DMF0014' AND PROCEDURE_NAME IN ('P_PR_DM_CUST_ITEM_MAPPING', 'P_PR_DM_PLN_CUST_FCST_TO_MKT_FCST', 'P_PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40') ORDER BY 2;  -- 기대 3행
SELECT OBJECT_NAME, OBJECT_TYPE FROM USER_OBJECTS WHERE STATUS = 'INVALID' AND OBJECT_TYPE IN ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION') ORDER BY 1;
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0014';
